#include <stdio.h>
#include <string.h>
#include <stdbool.h>

int main() {
    char s[100005];
    if (scanf("%s", s) != 1) {
        printf("true\n");
        return 0;
    }
    char stack[100005];
    int top = -1;
    for (int i = 0; s[i]; i++) {
        char c = s[i];
        if (c == '(') stack[++top] = ')';
        else if (c == '{') stack[++top] = '}';
        else if (c == '[') stack[++top] = ']';
        else {
            if (top == -1 || stack[top--] != c) {
                printf("false\n");
                return 0;
            }
        }
    }
    printf("%s\n", top == -1 ? "true" : "false");
    return 0;
}
